===== bamboo-spec-tag.yml =====
# yaml-language-server: $schema=../../schemas/json/bamboo-spec.json
version: 2

triggers:
  - tag:
      filter: v?[0-9]+\.[0-9]|\.[0-9].*
      description: Build on version number
      tagInBranch: false
      conditions:
        - green-plan:
            - PROJ-PLAN1
            - PROJ-PLAN2

===== bamboo-spec.yml =====
# yaml-language-server: $schema=../../schemas/json/bamboo-spec.json
---
version: 2
plan:
  project-key: TEST
  key: TE
  name: test
stages:
  - Default Stage:
      jobs:
        - Default Job
Default Job:
  key: JOB1
  tasks:
    - checkout:
        force-clean-build: 'false'
        description: Checkout Default Repository
triggers:
  - bitbucket-server-trigger
  - tag

branch-overrides:
  - master:
      stages:
        - Default Stage:
            jobs:
              - Default Job
        - Publish Master:
            manual: true
            jobs:
              - Publish Master Job

      Publish Master Job:
        tasks:
          - checkout:
              description: Checkout code for publish on the master
              force-clean-build: true

        requirements:
          - centos: '9'
          - Docker

        other:
          clean-working-dir: true

