+const AjvDraft04 = require('ajv-draft-04');
+const fs = require('fs');
+const schema = JSON.parse(fs.readFileSync('src/schemas/json/bamboo-spec.json','utf8'));
+const ajv = new AjvDraft04({ strict:false, allErrors:false });
+const validate = ajv.compile(schema);
+const cases = {
+  "server-name+plan enabled/rerunnable": {
+    version:2, "server-name":"My Bamboo",
+    plan:{ "project-key":"P", key:"K", name:"n", enabled:false, rerunnable:true }
+  },
+  "git repo full + change-detection quiet-period": {
+    version:2, repositories:[ { myrepo:{ type:"git", url:"ssh://x", branch:"m",
+      "shared-credentials":"sc", "ssh-key":"k", "ssh-key-passphrase":"p",
+      lfs:true, submodules:false, "use-shallow-clones":true,
+      "change-detection":{ "quiet-period":{ "quiet-period-seconds":10, "max-retries":3 },
+        "exclude-changeset-pattern":".*", "file-filter-type":"NONE", "file-filter-pattern":"x" } } } ]
+  },
+  "github/bitbucket-server/subversion repos": {
+    version:2, repositories:[
+      { gh:{ type:"github", repository:"o/r", user:"u", password:"pw", branch:"m" } },
+      { bs:{ type:"bitbucket-server", server:"s", project:"PR", slug:"sl", "clone-url":"c",
+        "public-key":"pub", "private-key":"priv" } },
+      { svn:{ "plugin-key":"com.x.svn", "server-config":{a:1}, "branch-config":{b:2} } },
+      { bb:{ type:"bitbucket", slug:"a/b" } } ]
+  },
+  "polling repositories+conditions+cron": {
+    version:2, triggers:[ { polling:{ period:180, cron:"0 0 * * ? *",
+      repositories:["r1","r2"], conditions:[ { "all-other-conditions":{ "x.enabled":true } } ] } } ]
+  },
+  "dependencies + branch-overrides + other": {
+    version:2, dependencies:{ "require-all-stages-passing":true, "enabled-for-branches":false,
+      "block-strategy":"none", plans:["A-B","C-D"] },
+    "branch-overrides":[ { "feature/*":{ version:2 } } ], other:{ anything:1 }
+  },
+  "job artifact-subscriptions + all task types": {
+    version:2, "My Job":{ key:"J",
+      "artifact-subscriptions":[ { artifact:"a", destination:"/d" }, {} ],
+      tasks:[
+        { script:{ interpreter:"/bin/sh", scripts:["echo hi"] } },
+        { script:["a","b"] },
+        { maven:{ executable:"mvn", jdk:"JDK", goal:"clean install", tests:"**/*Test", environment:"E", "working-dir":"wd", "project-file":"pom.xml", "use-return-code":true } },
+        { "inject-variables":"file.txt" },
+        { "inject-variables":{ file:"f", scope:"RESULT", namespace:"ns", conditions:[{x:{}}] } },
+        { "any-task":{ "plugin-key":"pk", configuration:{ a:"b" } } },
+        { "vcs-branch":{ branch:"b" } },
+        { "vcs-tag":{ tag:"v1" } },
+        { "vcs-commit":{ message:"m" } },
+        "clean",
+        { "test-parser":"junit" },
+        { "test-parser":{ type:"junit", "test-results":"r.xml", "ignore-time":true } },
+        { "test-parser":{ type:"mocha", "test-results":["a.json","b.json"] } },
+        { "artifact-download":{ destination:"/d", name:"N" } },
+        { "artifact-download":{ artifacts:[{ name:"n", destination:"/x" }] } },
+        { checkout:{ repository:"r", path:"p", "force-clean-build":true } },
+        { checkout:{ "force-clean-build":"false" } }
+      ],
+      "final-tasks":[ { "vcs-push":null }, { "vcs-push":{ repository:"r", "working-dir":"wd" } }, "clean" ] }
+  },
+  "deployment env with vcs-tag repo/working-dir + all notif events": {
+    version:2, deployment:{ name:"D", "source-plan":"P-K" }, environments:["Prod"],
+    "release-naming":{ "next-version-name":"1.0", "applies-to-branches":true, "auto-increment":true, "auto-increment-variables":["v"] },
+    Prod:{ tasks:[ { "vcs-tag":{ tag:"t", repository:"r", "working-dir":"wd" } } ],
+      notifications:[ { events:["deployment-started-and-finished","deployment-failed","deployment-finished"],
+        recipients:[ {users:["a"]},{groups:["g"]},{emails:["e@x"]},"responsible","watchers","committers" ] } ] }
+  },
+  "top-level notifications shorthands": {
+    version:2, notifications:[
+      { events:[ {"plan-failed":3}, {"plan-failed":{failures:2}}, "plan-completed",
+        {"job-error":{"first-only":true}}, "job-first-failed", "job-queued-without-capable-agents" ],
+        recipients:["responsible","watchers","committers", {users:["u"]}, {emails:["e@x"]}, {groups:["g"]}] } ]
+  }
+};
+let allok=true;
+for (const [name,doc] of Object.entries(cases)) {
+  const ok = validate(doc);
+  console.log((ok?'PASS':'FAIL')+' | '+name);
+  if(!ok){ allok=false; for(const e of validate.errors) console.log('    ->', e.instancePath, e.message, JSON.stringify(e.params)); }
+}
+process.exit(allok?0:1);
