+const AjvDraft04 = require('ajv-draft-04');
+const YAML = require('yaml');
+const fs = require('fs');
+const path = require('path');
+const schema = JSON.parse(fs.readFileSync('src/schemas/json/bamboo-spec.json','utf8'));
+const ajv = new AjvDraft04({ strict:false, allErrors:false });
+let validate;
+try { validate = ajv.compile(schema); } catch(e){ console.log('COMPILE ERROR:', e.message); process.exit(1); }
+const dir = 'src/test/bamboo-spec';
+for (const f of fs.readdirSync(dir).sort()) {
+  const raw = fs.readFileSync(path.join(dir,f),'utf8');
+  const data = f.endsWith('.json') ? JSON.parse(raw) : YAML.parse(raw);
+  const ok = validate(data);
+  console.log((ok?'PASS':'FAIL')+' '+f);
+  if(!ok) for(const e of validate.errors) console.log('   ->', e.instancePath, e.message, JSON.stringify(e.params));
+}
