+import Ajv from 'ajv-draft-04';
+import fs from 'fs';
+import path from 'path';
+import { fileURLToPath } from 'url';
+// yaml parse
+import { createRequire } from 'module';
+const require = createRequire(import.meta.url);
+let yaml;
+try { yaml = require('yaml'); } catch(e){ try { yaml = require('js-yaml'); } catch(e2){ console.log('no yaml lib'); } }
+
+const schema = JSON.parse(fs.readFileSync('src/schemas/json/bamboo-spec.json','utf8'));
+const ajv = new Ajv({ strict:false, allErrors:false });
+let validate;
+try { validate = ajv.compile(schema); } catch(e){ console.log('COMPILE ERROR:', e.message); process.exit(1); }
+
+const dir = 'src/test/bamboo-spec';
+for (const f of fs.readdirSync(dir)) {
+  const p = path.join(dir,f);
+  const raw = fs.readFileSync(p,'utf8');
+  let data;
+  if (f.endsWith('.json')) data = JSON.parse(raw);
+  else data = yaml.parse ? yaml.parse(raw) : yaml.load(raw);
+  const ok = validate(data);
+  console.log((ok?'PASS':'FAIL')+' '+f);
+  if(!ok) console.log('   ->', JSON.stringify(validate.errors[0]));
+}
